<?php
if(PHP_SAPI!=='cli'&&realpath($_SERVER['SCRIPT_FILENAME']??'')===realpath(__FILE__)){http_response_code(404);exit;}
require_once __DIR__.'/auth.php';require_once __DIR__.'/shu_pinjaman_helper.php';
if(!shuPinjamanSiap($db)){http_response_code(404);exit('Pembayaran tidak ditemukan.');}
$s=$db->prepare("SELECT h.*,p.kode_pinjaman,p.tanggal_lunas,a.nama_lengkap,a.kode_anggota,a.user_id member_user,src.nama_lengkap sumber_nama,u.nama_lengkap admin_nama FROM shu_hak_pinjaman h JOIN pinjaman p ON p.id=h.pinjaman_id JOIN anggota a ON a.id=h.anggota_id JOIN anggota src ON src.id=h.sumber_anggota_id LEFT JOIN users u ON u.id=h.dibayar_oleh WHERE h.id=? AND h.status_bayar='sudah'");$s->execute([(int)($_GET['id']??0)]);$r=$s->fetch(PDO::FETCH_ASSOC);
if(!$r||(!isAdmin()&&(!isAnggota()||(int)$r['member_user']!==(int)$_SESSION['user_id']))){http_response_code(404);exit('Pembayaran tidak ditemukan.');}
if(isset($_GET['bukti'])){$base=realpath(__DIR__.'/../uploads/pembayaran');$file=realpath(__DIR__.'/../uploads/'.$r['bukti']);if(!$base||!$file||strpos($file,$base.DIRECTORY_SEPARATOR)!==0||!is_file($file)){http_response_code(404);exit('Bukti tidak ditemukan.');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file);if(!in_array($mime,['image/png','image/jpeg','image/webp'],true)){http_response_code(404);exit;}header('Content-Type:'.$mime);header('Cache-Control:private,no-store');header('X-Content-Type-Options:nosniff');readfile($file);exit;}
$org=$db->query('SELECT * FROM koperasi WHERE id=1')->fetch(PDO::FETCH_ASSOC);$title='Kwitansi SHU #'.str_pad($r['id'],6,'0',STR_PAD_LEFT);$jenis=$r['jenis']==='referensi'?'Bonus referensi dari '.$r['sumber_nama']:'SHU pelunasan pribadi';
$body='<h2>'.layananEscape($org['nama']).'</h2><p>'.layananEscape($org['alamat']??'').'</p><h3>'.$title.'</h3><table cellpadding="7"><tr><td>Penerima</td><td>'.layananEscape($r['nama_lengkap'].' / '.$r['kode_anggota']).'</td></tr><tr><td>Pinjaman sumber</td><td>'.layananEscape($r['kode_pinjaman']).'</td></tr><tr><td>Jenis hak</td><td>'.layananEscape($jenis).'</td></tr><tr><td>Perhitungan</td><td>'.formatRupiah($r['dasar_pinjaman']).' × '.rtrim(rtrim(number_format($r['persen'],4,'.',''),'0'),'.').'%</td></tr><tr><td>Jumlah diterima</td><td><strong>'.formatRupiah($r['jumlah']).'</strong></td></tr><tr><td>Metode / referensi</td><td>'.layananEscape($r['metode'].' / '.$r['referensi']).'</td></tr><tr><td>Tanggal</td><td>'.layananEscape($r['dibayar_at']).'</td></tr><tr><td>Admin</td><td>'.layananEscape($r['admin_nama']).'</td></tr></table>';
if(isset($_GET['pdf'])){require_once __DIR__.'/../tcpdf/tcpdf.php';$pdf=new TCPDF('P','mm','A5',true,'UTF-8',false);$pdf->setPrintHeader(false);$pdf->SetTitle($title);$pdf->AddPage();$pdf->SetFont('dejavusans','',10);$pdf->writeHTML($body);$pdf->Output('Kwitansi-SHU-'.$r['id'].'.pdf','D');exit;}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $title ?></title><style>body{font-family:Arial,sans-serif;background:#f2f6f7;color:#173c48;margin:0;padding:24px}main{max-width:720px;background:#fff;margin:auto;padding:30px;border:1px solid #dae6e9;border-radius:14px}table{width:100%;font-size:14px}td{vertical-align:top;overflow-wrap:anywhere}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:25px}button,a{padding:10px 14px;color:#087f83;background:#fff;border:1px solid #bcd4d6;text-decoration:none;border-radius:8px;cursor:pointer}img{max-width:100%;max-height:500px}@media print{body,main{background:#fff;padding:0;border:0}nav,details{display:none}}</style></head><body><main><nav><a href="<?= isAdmin()?'shu_anggota.php':'shu_saya.php' ?>">Kembali</a><button onclick="window.print()">Cetak</button><a href="?id=<?= (int)$r['id'] ?>&pdf=1">Download PDF</a></nav><?= $body ?><details><summary>Lihat foto bukti pembayaran</summary><img src="?id=<?= (int)$r['id'] ?>&bukti=1" alt="Bukti pembayaran SHU"></details></main></body></html>
